// The database tables, written in JavaScript.
// drizzle-kit reads this file to generate SQL migrations, and our code imports
// it to build type-safe queries.

import { sql } from "drizzle-orm";
import { boolean, check, date, index, pgTable, text, timestamp, uuid, varchar } from "drizzle-orm/pg-core";
import {
  DEFAULT_PRIORITY,
  NOTES_MAX_LENGTH,
  PRIORITIES,
  REPEATS,
  TITLE_MAX_LENGTH,
} from "../lib/task-validation.js";
import { user } from "./auth-schema.js";

// Better Auth's tables (user, session, account, verification). That file is
// generated by `npx auth generate`, so don't edit it by hand.
export * from "./auth-schema.js";

export const tasks = pgTable(
  "tasks",
  {
    // The database creates a random unique id for every new row.
    id: uuid("id").primaryKey().defaultRandom(),

    // Who owns this task. Must point at a real user ("foreign key"); when that
    // user is deleted, their tasks are deleted too ("cascade").
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),

    // varchar(100) makes the database itself refuse longer titles: a second
    // safety net behind validateTaskTitle.
    title: varchar("title", { length: TITLE_MAX_LENGTH }).notNull(),

    completed: boolean("completed").notNull().default(false),

    // Optional due date. SQL "date" is just a calendar day: no time, no time
    // zone, so 15 Nov stays 15 Nov wherever the server runs. mode "string"
    // gives "2026-11-15" in JavaScript instead of a Date object, which would
    // bring time zones back in. Nullable: tasks without a date are fine.
    dueDate: date("due_date", { mode: "string" }),

    // "high", "medium" or "low". NOT NULL with a default, so adding this column
    // is safe: every existing task becomes "medium", and code that doesn't
    // know about priorities yet can still insert tasks.
    priority: text("priority").notNull().default(DEFAULT_PRIORITY),

    // Optional longer text. Nullable, so existing tasks simply have none.
    notes: varchar("notes", { length: NOTES_MAX_LENGTH }),

    // "daily", "weekly" or "monthly", or null for a one-off task. When a
    // repeating task is marked done, its due date moves forward instead.
    repeat: text("repeat"),

    // "created_at" in SQL, createdAt in JavaScript. Stored with time zone.
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    // Every query filters by user_id, so an index keeps that fast as tasks grow.
    index("tasks_user_id_idx").on(table.userId),

    // A CHECK constraint: the database itself refuses any other priority,
    // a second safety net behind validatePriority.
    check(
      "tasks_priority_check",
      sql.raw(`priority in (${PRIORITIES.map((p) => `'${p.value}'`).join(", ")})`),
    ),
    check(
      "tasks_repeat_check",
      sql.raw(`repeat in (${REPEATS.map((r) => `'${r.value}'`).join(", ")})`),
    ),
    // A repeating task must have a due date to move forward from.
    check("tasks_repeat_needs_due_date_check", sql`${table.repeat} is null or ${table.dueDate} is not null`),
  ],
);

// The checklist inside a task. A new table, rather than a column on tasks,
// because one task has many items: a "one-to-many" relationship.
//
// Items don't store their owner: they belong to a task, and the task belongs
// to a user. Every query checks ownership through the task.
export const subtasks = pgTable(
  "subtasks",
  {
    id: uuid("id").primaryKey().defaultRandom(),

    // The task this item is part of. Deleting the task deletes its items
    // (and deleting a user deletes their tasks, so their items go too).
    taskId: uuid("task_id")
      .notNull()
      .references(() => tasks.id, { onDelete: "cascade" }),

    title: varchar("title", { length: TITLE_MAX_LENGTH }).notNull(),
    completed: boolean("completed").notNull().default(false),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  // Items are always looked up by their task.
  (table) => [index("subtasks_task_id_idx").on(table.taskId)],
);

// A diary of "the user finished a task at this moment", for streaks.
// Its own table, not a column on tasks, because a repeating task is finished
// many times (each time it moves to its next date) but is only one row.
export const taskCompletions = pgTable(
  "task_completions",
  {
    id: uuid("id").primaryKey().defaultRandom(),

    // Owner, so streaks can be counted straight from this table.
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),

    // Which task. Deleting the task keeps the entry ("set null"): you still
    // did it that day, so the streak shouldn't break.
    taskId: uuid("task_id").references(() => tasks.id, { onDelete: "set null" }),

    // The exact moment, with time zone. Which *day* that was depends on the
    // user's time zone, so that's worked out when reading.
    completedAt: timestamp("completed_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("task_completions_user_id_completed_at_idx").on(table.userId, table.completedAt),
    index("task_completions_task_id_idx").on(table.taskId),
  ],
);
